static void vx_pitrex_tile (const char *path, const unsigned char *d, size_t n)   /* (made unless it is there at this size) */
{
	FILE *f = fopen (path, "rb"); if (f) { fseek (f, 0, SEEK_END); long have = ftell (f); fclose (f); if (have == (long) n) return; }
	f = fopen (path, "wb"); if (f) { fwrite (d, 1, n, f); fclose (f); }
}
/* thumbs: the folder system/vectrex_emu/thumbs - its carts and boxes folders must be there */
static void vx_pitrex_tiles_write (const char *thumbs)
{
	char p[1024]; snprintf (p, sizeof p, "%s/carts/PiTrex.png", thumbs); vx_pitrex_tile (p, VX_PITREX_CART, sizeof VX_PITREX_CART);
	snprintf (p, sizeof p, "%s/boxes/PiTrex.png", thumbs); vx_pitrex_tile (p, VX_PITREX_BOX, sizeof VX_PITREX_BOX);
}
